async function printReceipt(payment:any){if(!['super_admin','finance'].includes(profile?.role)){setError('Only Finance or Super Admin can print payment receipts.');return;}setSaving(true);setError('');try{const db=createClient();const [sr,cr,pr]=await Promise.all([db.from('college_students').select('*').eq('id',payment.student_id).maybeSingle(),db.from('college_fee_charges').select('*').eq('student_id',payment.student_id),db.from('college_payments').select('*').eq('student_id',payment.student_id)]);if(sr.error)throw sr.error;if(cr.error)throw cr.error;if(pr.error)throw pr.error;if(!sr.data)throw new Error('Student record could not be found for this receipt.');const student=sr.data;const totalCharges=(cr.data||[]).reduce((sum:any,r:any)=>sum+Math.max(0,Number(r.amount_kes||0)-Number(r.discount_kes||0)),0);const totalPaid=(pr.data||[]).reduce((sum:any,r:any)=>sum+Number(r.amount_kes||0),0);setPrintDoc({type:'receipt',autoPrint:false,title:'Official Fee Payment Receipt',fields:[{label:'Receipt number',value:'SMTC-'+String(payment.id||'').replaceAll('-','').slice(0,10).toUpperCase()},{label:'Student name',value:[student.first_name,student.middle_name,student.last_name].filter(Boolean).join(' ')},{label:'Admission number',value:student.admission_number},{label:'Programme',value:programmeLabel(student)},{label:'Payment date',value:payment.paid_at?new Date(payment.paid_at).toLocaleString('en-KE'):'—'},{label:'Payment method',value:optionLabel(String(payment.payment_method||'—'))},{label:'Bank / provider',value:payment.bank_name||'—'},{label:'Transaction reference',value:payment.reference_number||'—'},{label:'Amount received',value:money(payment.amount_kes)}],totals:[{label:'Total net charges',value:money(totalCharges)},{label:'Total paid',value:money(totalPaid)},{label:'Current account balance',value:money(totalCharges-totalPaid)}]});}catch(e){setError(e instanceof Error?e.message:'Could not prepare the receipt. Check Finance permissions and student records.');}finally{setSaving(false)}}
async function printStatement(studentId:string){if(!['super_admin','finance'].includes(profile?.role)){setError('Only Finance or Super Admin can print fee statements.');return;}setSaving(true);setError('');try{const db=createClient();const [sr,cr,pr]=await Promise.all([db.from('college_students').select('*').eq('id',studentId).maybeSingle(),db.from('college_fee_charges').select('*').eq('student_id',studentId).order('created_at',{ascending:true}),db.from('college_payments').select('*').eq('student_id',studentId).order('paid_at',{ascending:true})]);if(sr.error)throw sr.error;if(cr.error)throw cr.error;if(pr.error)throw pr.error;if(!sr.data)throw new Error('Student record not found.');const student=sr.data;const charges=cr.data||[];const payments=pr.data||[];const totalCharges=charges.reduce((sum:any,r:any)=>sum+Math.max(0,Number(r.amount_kes||0)-Number(r.discount_kes||0)),0);const totalPaid=payments.reduce((sum:any,r:any)=>sum+Number(r.amount_kes||0),0);setPrintDoc({type:'statement',title:'Student Fee Statement',fields:[{label:'Student name',value:[student.first_name,student.middle_name,student.last_name].filter(Boolean).join(' ')},{label:'Admission number',value:student.admission_number},{label:'Programme',value:programmeLabel(student)},{label:'Study mode',value:optionLabel(String(student.study_mode||'—'))},{label:'Intake',value:[student.intake,student.intake_year].filter(Boolean).join(' ')},{label:'Account printed',value:new Date().toLocaleDateString('en-KE')}],tables:[{title:'Charges & discounts',columns:['Description','Due date','Gross charge','Discount','Net charge','Status'],rows:charges.map((r:any)=>[r.description,r.due_date||'—',money(r.amount_kes),money(r.discount_kes),money(Math.max(0,Number(r.amount_kes||0)-Number(r.discount_kes||0))),optionLabel(String(r.charge_status||'—'))])},{title:'Payments recorded',columns:['Date','Method','Reference','Amount received'],rows:payments.map((r:any)=>[r.paid_at?new Date(r.paid_at).toLocaleDateString('en-KE'):'—',optionLabel(String(r.payment_method||'—')),r.reference_number||'—',money(r.amount_kes)])}],totals:[{label:'Total net charges',value:money(totalCharges)},{label:'Total paid',value:money(totalPaid)},{label:'Outstanding balance',value:money(totalCharges-totalPaid)}]});}catch(e){setError(e instanceof Error?e.message:'Could not prepare the student fee statement.');}finally{setSaving(false)}}
const renderField=(f:any)=>{const key=String(f[0]),label=String(f[1]),required=!!f[2],options=selectOptions[def[1]+'.'+key]||selectOptions[key];if(def[1]==='college_payments'&&key==='bank_name'&&values.payment_method!=='bank')return null;const emptyRelation=!!relationFields[key]&&!(lookupOptions[key]||[]).length;const setupLink=key==='fee_head_id'?'/workspace?module=college_fee_heads':key==='academic_period_id'?'/workspace?module=college_academic_periods':key==='student_id'?'/workspace?module=college_students':key==='programme_id'?'/workspace?module=college_programmes':'';return <label key={key}>{label}{required?' *':''}{def[1]==='college_payments'&&key==='bank_name'?<><select required={values.payment_method==='bank'} value={values[key]||''} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}><option value="">Choose bank and account</option>{financeBanks.map((b:any)=><option key={b.id} value={[b.bank_name,b.account_name,b.account_number,b.branch].filter(Boolean).join(' — ')}>{[b.bank_name,b.account_name,b.account_number,b.branch].filter(Boolean).join(' — ')}</option>)}</select><small className="field-help">Manage bank names and account details in <a href="/workspace?module=college_bank_accounts">Bank &amp; Payment Methods</a>.</small></>:relationFields[key]?<><select required={required} value={values[key]||''} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}><option value="">{emptyRelation?'No '+label.toLowerCase()+'s available':'Choose '+label.toLowerCase()}</option>{(lookupOptions[key]||[]).map(o=><option key={o.value} value={o.value}>{o.label}</option>)}</select>{emptyRelation&&setupLink&&<small className="field-help">No {label.toLowerCase()} records found. <a href={setupLink}>Add {label.toLowerCase()} first</a>, then return here.</small>}</>:options?<select required={required} value={values[key]||''} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}><option value="">Choose {label.toLowerCase()}</option>{options.map(option=><option key={option} value={option}>{optionLabel(option)}</option>)}</select>:key==='id'?<input value="Assigned automatically" disabled aria-label="System-managed user ID"/>:<input required={required} type={['date_of_birth','admission_date','starts_on','ends_on','session_date','due_date','registration_opens_on','registration_closes_on','examinations_start_on','examinations_end_on','teaching_practice_start_on','teaching_practice_end_on','approval_valid_until','visit_date'].includes(key)?'date':['intake_year','capacity','quantity','estimated_cost_kes','amount_kes','max_score','weekday','duration_terms','term_number','teacher_experience_years','credit_hours','contact_hours','practical_hours','year_number','placement_capacity','days_required','days_completed','final_score','score','maximum_score','discount_kes'].includes(key)?'number':key.toLowerCase().includes('email')?'email':'text'} min={key==='intake_year'?'1900':undefined} max={key==='intake_year'?'2200':undefined} value={values[key]||''} onChange={e=>setValues(v=>({...v,[key]:e.target.value}))}/>}</label>};
